// A malformed record must never become half a record.
const REQUIRED = ['id', 'email', 'occurred_at'];
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const missing = REQUIRED.filter(k => !j[k]);
  if (missing.length) {
    out.push({ json: { ...j, _refused: true, _why: 'missing ' + missing.join(', ') } });
    continue;
  }
  out.push({ json: { ...j, _refused: false } });
}
return out;

// The same event arrives twice more often than anyone expects.
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const fresh = [];
for (const item of $input.all()) {
  const key = String(item.json.id) + ':' + String(item.json.occurred_at);
  if (staticData.seen[key]) continue;
  staticData.seen[key] = Date.now();
  fresh.push(item);
}
return fresh;

// The vendor ceiling is respected here rather than discovered in
// production at the worst possible moment.
const PER_MINUTE = 60;
const items = $input.all();
const batches = [];
for (let i = 0; i < items.length; i += PER_MINUTE) {
  batches.push({ json: { batch: i / PER_MINUTE, size: items.slice(i, i + PER_MINUTE).length,
                          rows: items.slice(i, i + PER_MINUTE).map(x => x.json) } });
}
return batches;

// What was written, onto the record, in the client's own words.
return $input.all().map(i => ({ json: { ...i.json,
  note: 'Automation wrote: ' + (i.json.outcome || 'no change') + ' at ' + new Date().toISOString(),
  written_by: 'n8n', written_at: new Date().toISOString() } }));

// The decision that shapes the whole build: what the automation is
// allowed to WRITE versus what it may only flag for a person.
return $input.all().map(i => ({ json: { ...i.json,
  flagged: true, reason: i.json.why || 'below the confidence floor',
  assigned_to: 'ops queue' } }));

// Both paths get written down. A run nobody logged is a run nobody
// can explain three weeks later.
return $input.all().map(i => ({ json: {
  run_id: $execution.id, workflow: $workflow.name,
  path: i.json.flagged ? 'flagged' : (i.json.error ? 'error' : 'written'),
  record: i.json.id, at: new Date().toISOString() } }));

// A refused record is parked with its reason, never dropped.
return $input.all().map(i => ({ json: { ...i.json,
  parked_at: new Date().toISOString(), needs: i.json._why } }));

// The node most cheaper quotes leave out. The first trigger catches
// what happens; this one catches what did not.
// Sweep: orders from yesterday with no companion offer sent
const rows = $input.all().map(i => i.json);
const missed = rows.filter(r => !r.handled_at);
return missed.map(r => ({ json: { ...r, found_by: 'sweep', qualifies: true } }));

